import {mount} from 'cypress/react';
import {Harness,stubRpc,board} from '../support/harness';
const title=(key='TEST-1')=>cy.get(`[aria-label^="Open details for ${key}:"]`);
const button=(label:string)=>cy.get(`[role="button"][aria-label="${label}"]`);
describe('Dashboard',()=>{
 beforeEach(()=>cy.viewport(1440,900));
 it('loading → column placeholders, then real issues without a refresh flash',()=>{
  stubRpc();
  const gate:{release?:()=>void}={};
  cy.intercept('POST','/__rpc/board.read',request=>new Promise<void>(resolve=>{gate.release=()=>{request.reply(board);delete gate.release;resolve();};})).as('board');
  mount(<Harness/>);
  cy.get('[aria-label="Loading Jira dashboard"]').should('be.visible');
  title().should('not.exist');
  cy.wrap(gate).should(value=>expect(value.release).to.be.a('function')).then(value=>value.release!());cy.wait('@board');title().should('be.visible');
  button('Refresh').click();title().should('be.visible');
  cy.get('[aria-label="Loading Jira dashboard"]').should('not.exist');cy.wrap(gate).should(value=>expect(value.release).to.be.a('function')).then(value=>value.release!());cy.wait('@board');
 });
 it('search and sprint overlay → filtered cards without shifting columns',()=>{
  stubRpc();mount(<Harness/>);title().should('be.visible');
  cy.get('[aria-label="Search issues"]').type('Second');title().should('not.exist');title('TEST-2').should('be.visible');
  button('Clear search').click();
  title().then($title=>{
   const top=$title[0].getBoundingClientRect().top;
   button('Select sprint').click();cy.contains('Follow active sprint').should('be.visible');cy.contains('Old sprint').should('not.exist');
   title().should($next=>expect($next[0].getBoundingClientRect().top).to.equal(top));
  });
  button('Close dropdown').click();
  button('Expand parent and tags for TEST-1').click();cy.contains('beta').should('be.visible');
  button('Close issue details').should('not.exist');
 });
 it('failed board load → readable error without an endless spinner',()=>{
  stubRpc({error:true});mount(<Harness/>);
  cy.contains('Jira denied board access.').should('be.visible');
  cy.get('[aria-label="Loading Jira dashboard"]').should('not.exist');
 });
 it('long columns → independently scroll to the final issue',()=>{
  stubRpc({many:true});mount(<Harness/>);
  cy.get('[data-testid="board-column-0"]').should($el=>expect($el[0].scrollHeight).greaterThan($el[0].clientHeight)).scrollTo('bottom');
  title('TEST-18').should('be.visible');button('Settings').should('be.visible');
 });
 it('title → modal details, Escape → board',()=>{
  stubRpc();mount(<Harness/>);title().click();
  cy.contains('Description paragraph 1.').should('be.visible');
  button('Close issue details').should('be.visible');
  cy.get('[role="dialog"]').should('be.visible');
  button('Close issue details').focus();cy.realPress('Escape');button('Close issue details').should('not.exist');title().should('be.visible');
 });
});
describe('Dashboard details panel',()=>{
 beforeEach(()=>{cy.viewport(1440,900);stubRpc();});
 it('resize, collapse and workspace navigation → restore ticket and chosen width',()=>{
  mount(<Harness mode="panel"/>);title().click();
  cy.get('[data-testid="details-panel"]').should('have.css','width','520px');
  cy.get('[aria-label="Resize issue details panel"] > *').should('have.css','cursor','col-resize');
  cy.get('[aria-label="Resize issue details panel"]').realMouseDown({position:'center'}).realMouseMove(-100,0,{position:'center',keepMouseDownButton:'left'}).realMouseUp();
  cy.get('[data-testid="details-panel"]').should('have.css','width','620px');
  button('Collapse issue details').click();cy.get('[data-testid="details-panel"]').should('have.css','width','48px');
  cy.get('[data-testid="navigate"]').click();cy.contains('Simulated workspace').should('be.visible');cy.get('[data-testid="navigate"]').click();
  button('Expand issue details').should('be.visible').click();
  cy.get('[data-testid="details-panel"]').should('have.css','width','620px').and('contain.text','TEST-1');
  title('TEST-2').click();cy.get('[data-testid="details-panel"]').should('contain.text','TEST-2');
  cy.screenshot('desktop-details-panel',{capture:'viewport'});
 });
 it('collapse → preserve description scroll position and comment draft',()=>{
  mount(<Harness mode="panel"/>);title().click();
  cy.contains('Description paragraph 35.').should('exist');
  cy.get('[data-testid="details-panel-scroll"]').scrollTo('bottom');
  button('Add comment').click();cy.get('[aria-label="Write a comment in Markdown"]').type('An unfinished draft');
  button('Collapse issue details').click();button('Expand issue details').click();
  cy.get('[aria-label="Write a comment in Markdown"]').should('have.value','An unfinished draft');
  cy.get('[data-testid="details-panel-scroll"]').should($el=>expect($el[0].scrollTop).greaterThan(0));
  title('TEST-2').click();title().click();
  cy.get('[aria-label="Write a comment in Markdown"]').should('have.value','An unfinished draft');
  cy.get('[data-testid="navigate"]').click();cy.get('[data-testid="navigate"]').click();
  cy.get('[aria-label="Write a comment in Markdown"]').should('have.value','An unfinished draft');
 });
});

// Generated by Cypress Author, 2026-11-05.
for(const width of [1440,390])it(`workspace lookup unavailable → board stays usable and refresh clears warning at ${width}px`,()=>{
 cy.viewport(width,900);stubRpc();let failed=true;
 const warning='Some workspace links could not be checked. Jira issues are available; refresh to try again.';
 cy.intercept('POST','/__rpc/board.read',req=>req.reply({...board,...(failed?{workspaceWarning:warning}:{})})).as('board');
 mount(<Harness/>);cy.wait('@board');cy.contains(warning).should('be.visible');title().should('be.visible');
 button('Refresh').then(()=>{failed=false;}).click();cy.wait('@board');
 cy.contains(warning).should('not.exist');title().should('be.visible');
});

